import React, { useState, useContext } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { AuthContext } from '../../context/AuthContext';
import {
  FiMenu,
  FiX,
  FiUser,
  FiLogOut
} from 'react-icons/fi';

import NotificationBell from '../features/NotificationBell';
import DarkModeToggle from '../features/DarkModeToggle';
import logo from '../../assets/logo/logo.png';

const Navbar = () => {
  const { user, logout } = useContext(AuthContext);
  const navigate = useNavigate();
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [userDropdownOpen, setUserDropdownOpen] = useState(false);

  const handleLogout = () => {
    logout();
    navigate('/login');
    setUserDropdownOpen(false);
    setMobileMenuOpen(false);
  };

  return (
    <nav className="bg-white border-b border-gray-200 sticky top-0 z-50">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center h-16">

          {/* Logo — far left */}
          <Link to="/" className="flex items-center gap-2 shrink-0 mr-10">
            <img src={logo} alt="SkillBridge AI" className="h-8 w-auto object-contain" />
            <span className="text-lg font-semibold text-gray-900 leading-none">
              SkillBridge<span className="text-indigo-600 ml-0.5">AI</span>
            </span>
          </Link>

          {/* Desktop Navigation — center */}
          <nav className="hidden md:flex items-center gap-x-7 flex-1">
            <Link to="/" className="text-sm text-gray-600 hover:text-indigo-600 font-medium transition-colors">
              Home
            </Link>
            <Link to="/browse" className="text-sm text-gray-600 hover:text-indigo-600 font-medium transition-colors">
              Browse Projects
            </Link>
            <Link to="/how-it-works" className="text-sm text-gray-600 hover:text-indigo-600 font-medium transition-colors">
              How It Works
            </Link>
            <Link to="/about" className="text-sm text-gray-600 hover:text-indigo-600 font-medium transition-colors">
              About
            </Link>
          </nav>

          {/* Desktop Auth / Controls — far right */}
          <div className="hidden md:flex items-center gap-3 ml-auto shrink-0">
            <DarkModeToggle />
            <NotificationBell />

            {user ? (
              <div className="relative">
                <button
                  onClick={() => setUserDropdownOpen(!userDropdownOpen)}
                  className="flex items-center gap-2 px-3 py-1.5 bg-gray-50 hover:bg-gray-100 rounded-lg transition-all"
                >
                  <div className="w-7 h-7 bg-gradient-to-br from-indigo-500 to-indigo-700 rounded-full flex items-center justify-center">
                    <FiUser className="text-white" size={14} />
                  </div>
                  <span className="text-sm font-semibold text-gray-800">{user.name}</span>
                </button>

                {userDropdownOpen && (
                  <div className="absolute right-0 mt-2 w-48 bg-white rounded-lg shadow-xl border border-gray-100 py-1 animate-slide-down">
                    <Link
                      to="/dashboard"
                      onClick={() => setUserDropdownOpen(false)}
                      className="block px-4 py-2 text-sm text-gray-700 hover:bg-indigo-50 hover:text-indigo-600 transition-colors"
                    >
                      Dashboard
                    </Link>
                    <Link
                      to="/profile"
                      onClick={() => setUserDropdownOpen(false)}
                      className="block px-4 py-2 text-sm text-gray-700 hover:bg-indigo-50 hover:text-indigo-600 transition-colors"
                    >
                      Profile
                    </Link>
                    <hr className="my-1" />
                    <button
                      onClick={handleLogout}
                      className="w-full text-left px-4 py-2 text-sm text-red-600 hover:bg-red-50 transition-colors flex items-center gap-2"
                    >
                      <FiLogOut size={14} />
                      <span>Logout</span>
                    </button>
                  </div>
                )}
              </div>
            ) : (
              <div className="flex items-center gap-2">
                <Link to="/login" className="px-4 py-1.5 text-sm text-gray-700 hover:text-indigo-600 font-medium transition-colors">
                  Login
                </Link>
                <Link
                  to="/register"
                  className="px-5 py-1.5 text-sm bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 font-semibold transition-all shadow-sm hover:shadow-md"
                >
                  Sign Up
                </Link>
              </div>
            )}
          </div>

          {/* Mobile Menu Button */}
          <button
            onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
            className="md:hidden p-2 text-gray-700 hover:text-indigo-600 transition-colors"
          >
            {mobileMenuOpen ? <FiX size={22} /> : <FiMenu size={22} />}
          </button>
        </div>

        {/* Mobile Menu */}
        {mobileMenuOpen && (
          <div className="md:hidden py-3 border-t border-[#E2E8F0] animate-slide-down">
            <div className="flex flex-col space-y-1">
              <Link to="/" onClick={() => setMobileMenuOpen(false)} className="px-3 py-2 rounded-lg text-sm text-gray-700 hover:bg-indigo-50 hover:text-indigo-600 font-medium transition-colors">
                Home
              </Link>
              <Link to="/browse" onClick={() => setMobileMenuOpen(false)} className="px-3 py-2 rounded-lg text-sm text-gray-700 hover:bg-indigo-50 hover:text-indigo-600 font-medium transition-colors">
                Browse Projects
              </Link>
              <Link to="/how-it-works" onClick={() => setMobileMenuOpen(false)} className="px-3 py-2 rounded-lg text-sm text-gray-700 hover:bg-indigo-50 hover:text-indigo-600 font-medium transition-colors">
                How It Works
              </Link>
              <Link to="/about" onClick={() => setMobileMenuOpen(false)} className="px-3 py-2 rounded-lg text-sm text-gray-700 hover:bg-indigo-50 hover:text-indigo-600 font-medium transition-colors">
                About
              </Link>

              <hr className="my-2 border-[#E2E8F0]" />

              {user ? (
                <>
                  <Link to="/dashboard" onClick={() => setMobileMenuOpen(false)} className="px-3 py-2 rounded-lg text-sm text-gray-700 hover:bg-gray-100 font-medium">
                    Dashboard
                  </Link>
                  <Link to="/profile" onClick={() => setMobileMenuOpen(false)} className="px-3 py-2 rounded-lg text-sm text-gray-700 hover:bg-gray-100 font-medium">
                    Profile
                  </Link>
                  <button onClick={handleLogout} className="w-full text-left px-3 py-2 rounded-lg text-sm text-red-600 hover:bg-red-50 font-medium">
                    Logout
                  </button>
                </>
              ) : (
                <div className="flex flex-col gap-2 pt-2">
                  <Link to="/login" onClick={() => setMobileMenuOpen(false)} className="px-4 py-2 text-sm text-gray-700 bg-gray-50 rounded-lg text-center font-medium">
                    Login
                  </Link>
                  <Link to="/register" onClick={() => setMobileMenuOpen(false)} className="px-4 py-2 text-sm bg-indigo-600 text-white rounded-lg text-center font-semibold">
                    Sign Up
                  </Link>
                </div>
              )}
            </div>
          </div>
        )}
      </div>
    </nav>
  );
};

export default Navbar;
